  const [weeklyScheduleLoaded, setWeeklyScheduleLoaded] = useState<boolean>(false);
  // Lịch tuần theo NGÀY THẬT: tuần đang xem (0 = tuần này), lịch đang sửa
  const [weekOffset, setWeekOffset] = useState(0);
  const [currentTodayIso, setCurrentTodayIso] = useState<string>(() => todayVN());
  const [editingScheduleId, setEditingScheduleId] = useState<number | null>(null);
  // Xem chi tiết một lịch (họp / công tác) — mọi người liên quan đều xem được, kể cả không có quyền sửa
  const [viewingScheduleEvent, setViewingScheduleEvent] = useState<any | null>(null);

  const computeWeekByOffset = useCallback((offset: number, baseTodayIso: string = currentTodayIso) => {
    const base = new Date((baseTodayIso || todayVN()) + "T00:00:00");
    const dow = (base.getDay() + 6) % 7; // 0 = Thứ 2
    const monday = new Date(base);
    monday.setDate(base.getDate() - dow + offset * 7);
    const iso = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    const names = ["Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7"];
    const days = names.map((name, i) => {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      return { name, date: iso(d), label: `${String(d.getDate()).padStart(2, "0")}/${String(d.getMonth() + 1).padStart(2, "0")}` };
    });
    const sundayDate = new Date(monday);
    sundayDate.setDate(monday.getDate() + 6);
    const sundayObj = { name: "Chủ nhật", date: iso(sundayDate), label: `${String(sundayDate.getDate()).padStart(2, "0")}/${String(sundayDate.getMonth() + 1).padStart(2, "0")}` };
    const all7Days = [...days, sundayObj];
    // Số tuần ISO-8601
    const t = new Date(Date.UTC(monday.getFullYear(), monday.getMonth(), monday.getDate() + 3));
    const firstThu = new Date(Date.UTC(t.getUTCFullYear(), 0, 4));
    const weekNo = 1 + Math.round(((t.getTime() - firstThu.getTime()) / 86400000 - 3 + ((firstThu.getUTCDay() + 6) % 7)) / 7);
    return {
      offset,
      days,
      all7Days,
      weekNo,
      year: t.getUTCFullYear(),
      startDate: days[0].date,
      endDate: sundayObj.date,
      rangeLabel: `${days[0].label} – ${days[5].label}`
    };
  }, [currentTodayIso]);

  const viewedWeek = useMemo(() => computeWeekByOffset(weekOffset, currentTodayIso), [computeWeekByOffset, weekOffset, currentTodayIso]);

  const weekSelectorOptions = useMemo(() => {
    const opts: Array<{ offset: number; label: string }> = [];
    for (let off = -12; off <= 4; off++) {
      const w = computeWeekByOffset(off, currentTodayIso);
      const tag = off === 0 ? " • Tuần hiện tại" : off === -1 ? " • Tuần trước" : off === 1 ? " • Tuần sau" : "";
      opts.push({
        offset: off,
        label: `Tuần ${w.weekNo}/${w.year} (${w.days[0].label} – ${w.days[5].label})${tag}`
      });
    }
    if (!opts.some(o => o.offset === weekOffset)) {
      const w = viewedWeek;
      opts.push({
        offset: weekOffset,
        label: `Tuần ${w.weekNo}/${w.year} (${w.days[0].label} – ${w.days[5].label})`
      });
      opts.sort((a, b) => a.offset - b.offset);
    }
    return opts;
  }, [computeWeekByOffset, currentTodayIso, weekOffset, viewedWeek]);
  // Lịch cũ chỉ lưu "Thứ 2"... (không có ngày): hiển thị ở tuần hiện tại; hỗ trợ cả lịch kéo dài từ date -> endDate
  const scheduleOnDay = (s: any, day: { name: string; date: string }) => {
    if (s.date) {
      const startIso = String(s.date).slice(0, 10);
      const endIso = s.endDate ? String(s.endDate).slice(0, 10) : startIso;
      if (endIso >= startIso) {
        return day.date >= startIso && day.date <= endIso;
      }
      return startIso === day.date;
    }
    return weekOffset === 0 && s.day === day.name;
  };

  // Khử trùng lặp thẻ lịch công tác tuần (do đồng bộ nhiều lần từ báo cáo tuần Kinh Doanh / Application)
  const dedupeWeeklySchedules = useCallback((rawList: any[]): any[] => {
    if (!Array.isArray(rawList)) return [];
    const seen = new Set<string>();
    const result: any[] = [];
    // Lịch "Từ ngày → Đến ngày" bản cũ lưu MỖI NGÀY một thẻ nhưng thẻ nào cũng kéo tới ngày cuối -> ngày thứ n hiện n thẻ.
    // Thẻ kéo dài mà trong khoảng đó đã có thẻ riêng cùng nội dung: thu về đúng ngày của nó.
    const normalized = collapseRangeScheduleCopies(rawList, canonStaffName);
    for (const s of normalized) {
      if (!s || typeof s !== "object") continue;
      const dateOrDay = s.date ? String(s.date).slice(0, 10) : String(s.day || "").trim();
      const timeStr = String(s.time || "").trim();
      const actorStr = canonStaffName(s.actor || "");
      const titleStr = canonStaffName(s.title || "");
      const locStr = canonStaffName(s.location || "");
      const sig = `${dateOrDay}|${timeStr}|${actorStr}|${titleStr}|${locStr}`;
      if (seen.has(sig)) continue;
      seen.add(sig);
      result.push(s);
    }
    return result;
  }, []);
  const resolveStaffDept = useCallback((staffName: string): string => {
    if (!staffName) return "";
    const pMatch = (personnelList || []).find((p: any) => sameStaffName(p.full_name || p, staffName));
    if (pMatch?.department) return normalizeWorkspaceDept(pMatch.department);
    const uMatch = (workspaceUsersList || []).find((u: any) => sameStaffName(u.full_name || u.username, staffName));
    if (uMatch?.department) return normalizeWorkspaceDept(uMatch.department);
    return "";
  }, [personnelList, workspaceUsersList]);

  const resolveUserIdForStaffName = useCallback((staffName: string): number | null => {
    if (!staffName) return null;
    if (sameStaffName(staffName, currentStaffName) && Number((user as any)?.id) > 0) {
      return Number((user as any).id);
    }
    const uMatch = (workspaceUsersList || []).find((u: any) => sameStaffName(u.full_name || u.username, staffName));
    return uMatch?.id ? Number(uMatch.id) : null;
  }, [workspaceUsersList, currentStaffName, user]);

  const navigateToTargetTab = useCallback((tab: string) => {
    if (typeof window === "undefined" || !tab || tab === "workspace") return;
    window.dispatchEvent(new CustomEvent("tbr-navigate", { detail: { tab } }));
  }, []);

  const persistCompanyResources = useCallback(async (nextList: CompanyResourceItem[]) => {
    setCompanyResources(nextList);
    try {
      if (typeof window !== "undefined") {
        localStorage.setItem("unified_company_resources", JSON.stringify(nextList));
      }
      await fetch("/api/storage?key=unified_company_resources", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(nextList)
      });
    } catch (err) {
      console.warn("Could not save company resources:", err);
    }
  }, []);

  const handleOpenEditResource = useCallback((resItem: CompanyResourceItem) => {
    setEditingResourceId(resItem.id);
    setNewResourceForm({
      name: resItem.name,
      category: resItem.category,
      capacityOrSpec: resItem.capacityOrSpec || "",
      icon: resItem.icon || "🏢"
    });
    setIsAddingNewResource(true);
  }, []);

  const handleDeleteResource = useCallback(
    async (resItem: CompanyResourceItem) => {
      if (typeof window !== "undefined" && !window.confirm(`Bạn có chắc muốn xóa tài nguyên "${resItem.name}" khỏi danh mục Công ty?`)) {
        return;
      }
      const nextList = companyResources.filter((r) => r.id !== resItem.id);
      await persistCompanyResources(nextList);
      if (selectedResourceFilter === resItem.id) {
        setSelectedResourceFilter("all");
      }
      if (editingResourceId === resItem.id) {
        setEditingResourceId(null);
        setIsAddingNewResource(false);
      }
      showToast(`🗑️ Đã xóa tài nguyên "${resItem.name}" khỏi danh mục!`, "info");
    },
    [companyResources, persistCompanyResources, selectedResourceFilter, editingResourceId, showToast]
  );

  // Phân tích chuỗi khung giờ (VD: "08:30 - 10:00", "8h30-11h") thành số phút [startMin, endMin] để kiểm tra trùng lịch phòng họp / tài nguyên
  const parseScheduleTimeRangeMinutes = useCallback((timeStr?: string): [number, number] | null => {
    const raw = String(timeStr || "").trim();
    if (!raw) return null;
    const m = raw.match(/(\d{1,2})\s*[:hH]\s*(\d{0,2})\s*[-–→tođến]+\s*(\d{1,2})\s*[:hH]\s*(\d{0,2})/i);
    if (m) {
      const sh = Math.min(23, Math.max(0, Number(m[1]) || 0));
      const sm = Math.min(59, Math.max(0, Number(m[2] || "0") || 0));
      const eh = Math.min(23, Math.max(0, Number(m[3]) || 0));
      const em = Math.min(59, Math.max(0, Number(m[4] || "0") || 0));
      const start = sh * 60 + sm;
      const end = eh * 60 + em;
      if (end > start) return [start, end];
    }
    const lower = raw.toLowerCase();
    if (lower.includes("cả ngày") || lower.includes("toàn thời gian")) return [8 * 60, 17 * 60 + 30];
    if (lower.includes("sáng")) return [8 * 60, 12 * 60];
    if (lower.includes("chiều")) return [13 * 60 + 30, 17 * 60 + 30];
    return null;
  }, []);

  // Nhận diện một lịch thật sự là Lịch Họp (loại trừ các việc chuẩn bị trước cuộc họp như "Chuẩn bị nội dung trước cuộc họp...")
  const isScheduleRealMeeting = useCallback((sched: any): boolean => {
    if (!sched) return false;
    if (sched.eventType === "RESOURCE") return false;
    if (sched.eventType === "MEETING") return true;
    if (sched.eventType === "WORK") return false;
    const titleStr = String(sched.title || "").trim();
    if (!titleStr) return false;
    if (/^(?:chuẩn\s*bị|soạn|tổng\s*hợp|lập|viết|gửi|hoàn\s*thiện|báo\s*cáo\s*trước)\b/i.test(titleStr)) {
      return false;
    }
    return /\bhọp\b/i.test(titleStr);
  }, []);

  // Nhận diện một lịch đăng ký sử dụng tài nguyên công ty (độc lập hoàn toàn với Lịch công tác & Lịch họp: chỉ tính các lịch có eventType === "RESOURCE" và không phải lịch họp nội bộ)
  const matchScheduleToResource = useCallback((sched: any, resItem: CompanyResourceItem): boolean => {
    if (!sched || !resItem) return false;
    if (sched.eventType !== "RESOURCE") return false;
    const titleStr = String(sched.title || "").trim();
    if (/^họp\b|^họp:/i.test(titleStr)) return false;
    if (sched.resourceId) {
      return sched.resourceId === resItem.id;
    }
    const rName = canonStaffName(resItem.name);
    if (!rName) return false;
    if (sched.resourceName && canonStaffName(sched.resourceName) === rName) {
      return true;
    }
    const loc = canonStaffName(sched.location || "");
    if (loc && loc === rName) return true;
    return false;
  }, []);

  // Tìm tất cả lịch đặt trùng tài nguyên & khung giờ trên danh sách ngày targetDates
  const findResourceTimeConflicts = useCallback(
    (
      resourceIdOrName: string,
      targetDates: string[],
      timeStr: string,
      excludeScheduleId?: number | null
    ): Array<{ schedule: any; date: string; resource: CompanyResourceItem }> => {
      if (!resourceIdOrName) return [];
      const resObj =
        companyResources.find((r) => r.id === resourceIdOrName) ||
        companyResources.find((r) => canonStaffName(r.name) === canonStaffName(resourceIdOrName));
      if (!resObj) return [];

      const reqRange = parseScheduleTimeRangeMinutes(timeStr);
      const conflicts: Array<{ schedule: any; date: string; resource: CompanyResourceItem }> = [];

      for (const isoDate of targetDates) {
        for (const s of weeklySchedule) {
          if (!s || (excludeScheduleId && s.id === excludeScheduleId)) continue;
          if (!matchScheduleToResource(s, resObj)) continue;
          const sStart = s.date ? String(s.date).slice(0, 10) : "";
          const sEnd = s.endDate ? String(s.endDate).slice(0, 10) : sStart;
          const onDate = sStart ? isoDate >= sStart && isoDate <= sEnd : false;
          if (!onDate) continue;

          const existRange = parseScheduleTimeRangeMinutes(s.time);
          const isOverlap =
            reqRange && existRange
              ? reqRange[0] < existRange[1] && existRange[0] < reqRange[1]
              : String(s.time || "").trim().toLowerCase() === String(timeStr || "").trim().toLowerCase();

          if (isOverlap) {
            conflicts.push({ schedule: s, date: isoDate, resource: resObj });
          }
        }
      }
      return conflicts;
    },
    [companyResources, weeklySchedule, parseScheduleTimeRangeMinutes, matchScheduleToResource]
  );

  const openScheduleForm = (
    date?: string,
    item?: any,
    defaultEventType: "WORK" | "MEETING" | "RESOURCE" = "WORK",
    preselectedResourceId?: string
  ) => {
    const defaultActor = selectedAssignee !== "all" && selectedAssignee !== "__UNASSIGNED__"
      ? selectedAssignee
      : (currentStaffName || departmentStaffList[0]?.full_name || "");
    const actorRealDept = resolveStaffDept(defaultActor);
    const fallbackDept = rolePerspective === "manager"
      ? managerDept
      : (selectedDept !== "all" && !isWorkspaceBlockKey(selectedDept)
          ? selectedDept
          : defaultConcreteDeptForScope(selectedDept, actorRealDept || userDept));
    const defaultCategory = SCHEDULE_VALID_CATEGORIES.includes(fallbackDept)
      ? fallbackDept
      : (SCHEDULE_VALID_CATEGORIES.includes(actorRealDept) ? actorRealDept : "Kinh Doanh");
    const today = todayVN();
    const pick = date || (viewedWeek.days.some(d => d.date === today) ? today : viewedWeek.days[0].date);
    setAttendeeSearchQuery("");
    setScheduleBatchItems([]);
    setScheduleScopeMode("person");
    setScheduleWorkSearch("");
    if (item) {
      const itemDate = item.date ? String(item.date).slice(0, 10) : (viewedWeek.days.find(d => d.name === item.day)?.date || pick);
      const itemEndDate = item.endDate ? String(item.endDate).slice(0, 10) : itemDate;
      const rawTime = String(item.time || "08:30 - 11:30").trim();
      const rangeMatch = rawTime.match(/^(\d{1,2}:\d{2})\s*[-–→]\s*(\d{1,2}:\d{2})/);
      const parsedActors = String(item.actor || "").split(/[,;\n]+/).map((s: string) => s.trim()).filter(Boolean);
      const hostActor = parsedActors[0] || defaultActor;
      const existingCoActors = Array.isArray(item.coActors) && item.coActors.length > 0
        ? item.coActors
        : parsedActors.slice(1);
      const matchedRes =
        companyResources.find((r) => r.id === item.resourceId) ||
        companyResources.find((r) => matchScheduleToResource(item, r));
      setEditingScheduleId(item.id);
      setScheduleForm({
        day: item.day,
        date: itemDate,
        endDate: itemEndDate,
        selectedDates: [itemDate],
        dateMode: itemEndDate > itemDate ? "RANGE" : "SINGLE",
        startTime: rangeMatch ? rangeMatch[1] : "08:30",
        endTime: rangeMatch ? rangeMatch[2] : "11:30",
        time: rawTime,
        category: item.category || defaultCategory,
        title: item.title || "",
        actor: hostActor,
        coActors: existingCoActors,
        location: item.location || matchedRes?.name || "",
        resourceId: item.resourceId || matchedRes?.id || "",
        resourceName: item.resourceName || matchedRes?.name || "",
        linkedTaskCodes: Array.isArray(item.linkedTaskCodes) ? item.linkedTaskCodes : [],
        autoCreateTask: false,
        eventType:
          item.eventType ||
          (matchedRes && matchedRes.category !== "MEETING_ROOM"
            ? "RESOURCE"
            : String(item.title || "").toLowerCase().includes("họp")
            ? "MEETING"
            : "WORK"),
        meetingAgenda: item.meetingAgenda || "",
        meetingLink: item.meetingLink || "",
        sendChatNotify: item.sendChatNotify !== undefined ? item.sendChatNotify : true,
        createMeetingGroup: item.createMeetingGroup !== undefined ? item.createMeetingGroup : true,
        sendBellNotify: item.sendBellNotify !== undefined ? item.sendBellNotify : true,
        reminderMinutes: item.reminderMinutes !== undefined ? Number(item.reminderMinutes) : 30,
        customNotifyMessage: item.customNotifyMessage || "",
        chatChannelId: item.chatChannelId,
        lastRemindedAt: item.lastRemindedAt,
        isPublic: Boolean(item.isPublic || item.resourceId || matchedRes),
        attachments: item.attachments || []
      });
    } else {
      setEditingScheduleId(null);
      const isMeeting = defaultEventType === "MEETING";
      const isResourceBooking = defaultEventType === "RESOURCE";
      const defaultRes =
        (preselectedResourceId && companyResources.find((r) => r.id === preselectedResourceId)) ||
        (isMeeting || isResourceBooking ? companyResources[0] : undefined);
      const isSchedulingForOtherStaff =
        !isMeeting &&
        !isResourceBooking &&
        Boolean(defaultActor) &&
        Boolean(currentStaffName) &&
        !sameStaffName(defaultActor, currentStaffName);
      setScheduleForm({
        day: viewedWeek.all7Days.find(d => d.date === pick)?.name || "Thứ 2",
        date: pick,
        endDate: pick,
        selectedDates: [pick],
        dateMode: "SINGLE",
        startTime: isMeeting || isResourceBooking ? "08:30" : "08:30",
        endTime: isMeeting || isResourceBooking ? "10:00" : "11:30",
        time: isMeeting || isResourceBooking ? "08:30 - 10:00" : "08:30 - 11:30",
        category: isMeeting ? "Họp & Giao Ban" : defaultCategory,
        title: "",
        actor: defaultActor,
        coActors: [],
        location: defaultRes ? defaultRes.name : isMeeting ? "Phòng họp chính Công ty (Tầng 2)" : "",
        resourceId: defaultRes ? defaultRes.id : "",
        resourceName: defaultRes ? defaultRes.name : "",
        linkedTaskCodes: [],
        autoCreateTask: isSchedulingForOtherStaff,
        eventType: defaultEventType,
        meetingAgenda: "",
        meetingLink: "",
        sendChatNotify: true,
        createMeetingGroup: isMeeting,
        sendBellNotify: true,
        reminderMinutes: 30,
        customNotifyMessage: "",
        isPublic: isMeeting || isResourceBooking || Boolean(defaultRes),
        attachments: []
      });
    }
    setIsScheduleModalOpen(true);
  };

  const openScheduleForHubItem = useCallback((item: {
    code?: string;
    task_code?: string;
    title?: string;
    department?: string;
    dept?: string;
    assignee_name?: string;
    assignees?: string[];
    customer_name?: string;
    location?: string;
  }) => {
    const code = String(item.task_code || item.code || "").trim();
    const titleRaw = String(item.title || "").trim();
    const combinedTitle = code && !titleRaw.toUpperCase().includes(code.toUpperCase())
      ? `[${code}] ${titleRaw}`
      : titleRaw;
    const rawAssignees = Array.isArray(item.assignees) && item.assignees.length > 0
      ? item.assignees
      : String(item.assignee_name || "").split(/[,;\n]+/).map((s) => cleanWorkspaceAssignee(s)).filter(Boolean);
    const preferredActor = (selectedAssignee !== "all" && selectedAssignee !== "__UNASSIGNED__"
      ? selectedAssignee
      : rawAssignees[0]) || currentStaffName || "";
    const itemDept = normalizeWorkspaceDept(item.department || item.dept || "") || resolveStaffDept(preferredActor);
    const validCat = SCHEDULE_VALID_CATEGORIES.includes(itemDept) ? itemDept : "Nghiên Cứu R&D";
    openScheduleForm(todayVN(), undefined, "WORK");
    setScheduleForm((prev) => ({
      ...prev,
      actor: preferredActor || prev.actor,
      category: validCat,
      title: combinedTitle || prev.title,
      location: String(item.location || item.customer_name || "").trim() || prev.location,
      linkedTaskCodes: code ? [code] : []
    }));
  }, [selectedAssignee, currentStaffName, resolveStaffDept]); // eslint-disable-line react-hooks/exhaustive-deps

  const [isLabProjectModalOpen, setIsLabProjectModalOpen] = useState(false);
  const [editingThematicId, setEditingThematicId] = useState<string | null>(null);
  const [thematicFilterType, setThematicFilterType] = useState<string>("all");
  const [labProjects, setLabProjects] = useState<any[]>([]);
  const [labProjectForm, setLabProjectForm] = useState({
    id: "DA-01",
    name: "",
    dept: "Liên Phòng Ban",
    participatingDepts: [] as string[],
    customerOrRef: "",
    typeId: "cross_hospital_tender",
    typeName: "Dự Án Đấu Thầu & Cung Ứng Trọn Gói Bệnh Viện",
    lead: "",
    collaborators: [] as string[],
    startDate: todayVN(),
    endDate: todayVN(),
    slot: "Toàn thời gian (Theo tiến trình)",
    priority: "Cao" as "Cao" | "Trung bình" | "Bình thường",
    status: "Active" as "Planning" | "Active" | "Review" | "Completed",
    tasksCount: 0,
    budget: "",
    description: "",
    stages: [] as Array<{
      id: string;
      name: string;
      dept?: string;
      depts?: string[];
      due?: string;
      status: "pending" | "in_progress" | "completed";
      assignee?: string;
      estimatedDays?: number;
      tasks?: Array<{
        id: string;
        title: string;
        dept?: string;
        assignee?: string;
        due?: string;
        status: "pending" | "in_progress" | "completed";
      }>;
    }>
  });
  const [quickTaskStageKey, setQuickTaskStageKey] = useState<string | null>(null);
  const [quickStageTaskForm, setQuickStageTaskForm] = useState<{
    title: string;
    dept: string;
    assignee: string;
    due: string;
  }>({ title: "", dept: "Kinh Doanh", assignee: "", due: todayVN() });

  const [isSalesTargetModalOpen, setIsSalesTargetModalOpen] = useState(false);
  const [salesTargets, setSalesTargets] = useState<any[]>([]);
  const [salesTargetForm, setSalesTargetForm] = useState({
    customer: "",
    amount: "2.5 Tỷ VNĐ",
    quarter: "Q4/2026",
    lead: "",
    description: "",
    stage: "Đang chào giá & Demo"
  });

  // Task Form State
  const [taskForm, setTaskForm] = useState({
    id: null as any,
    title: "",
    department: "Kinh Doanh",
    task_category: "Chăm sóc KH",
    assignee_name: "",
    customer_name: "",
    priority: "MEDIUM",
    status: "TODO",
    deadline: todayVN(),
    description: "",
    result: "",
    attachments: [] as any[],
    followers: [] as string[]
  });
  // Trạng thái của công việc lúc mở form sửa: để không ghi đè tiến độ người khác vừa cập nhật khi người sửa không đổi trạng thái
  const taskBaseStatusRef = useRef<string | null>(null);
  useEffect(() => {
    if (isTaskModalOpen) taskBaseStatusRef.current = (taskForm as any)?.id ? String((taskForm as any).status || "") : null;
  }, [isTaskModalOpen]); // eslint-disable-line react-hooks/exhaustive-deps

  const parseTaskFollowersList = useCallback((raw: any): string[] => {
    if (!raw) return [];
    let arr: any[] = [];
    if (Array.isArray(raw)) {
      arr = raw;
    } else if (typeof raw === "string") {
      const trimmed = raw.trim();
      if (!trimmed) return [];
      if (trimmed.startsWith("[")) {
        try {
          const parsed = JSON.parse(trimmed);
          if (Array.isArray(parsed)) arr = parsed;
        } catch {
          arr = trimmed.split(/[,;\n]+/);
        }
      } else {
        arr = trimmed.split(/[,;\n]+/);
      }
    }
    const out: string[] = [];
    const seen = new Set<string>();
    for (const item of arr) {
      const name = String(typeof item === "object" && item ? item.full_name || item.name || "" : item || "")
        .replace(/\s*\(.*?\)/g, "")
        .trim();
      if (!name) continue;
      const key = canonStaffName(name);
      if (!key || seen.has(key)) continue;
      seen.add(key);
      out.push(name);
    }
    return out;
  }, []);

