  const getInitialDailyDay = (isoStr?: string) => {
    const dStr = isoStr || todayVN();
    const dObj = new Date(dStr + "T00:00:00");
    const dayIndex = isNaN(dObj.getTime()) ? new Date().getDay() : dObj.getDay();
    const map = ["Thứ 7", "Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7"];
    return map[dayIndex] || "Thứ 2";
  };

  const [selectedDailyDay, setSelectedDailyDay] = useState<string>(() => getInitialDailyDay(todayVN()));
