  // Tự động cập nhật ngày hôm nay (theo giờ VN) khi qua ngày mới hoặc khi người dùng quay lại tab trình duyệt,
  // đảm bảo Nhật ký Daily & Lịch tuần luôn hiển thị đúng tuần hiện tại thay vì bị kẹt ở tuần cũ.
  useEffect(() => {
    const syncToday = () => {
      const latestToday = todayVN();
      setCurrentTodayIso(prev => {
        if (prev !== latestToday) {
          setWeekOffset(0);
          setSelectedDailyDay(getInitialDailyDay(latestToday));
          return latestToday;
        }
        return prev;
      });
    };
    syncToday();
    const timer = setInterval(syncToday, 60_000);
    window.addEventListener("focus", syncToday);
    return () => {
      clearInterval(timer);
      window.removeEventListener("focus", syncToday);
    };
  }, []);

  // Hàm nhảy tới bất kỳ ngày nào trên lịch (tự động đổi tuần tương ứng & chọn đúng Thứ trong tuần đó)
  const jumpDailyToDate = useCallback((targetIso: string) => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(targetIso)) return;
    const base = new Date(currentTodayIso + "T00:00:00");
    const baseDow = (base.getDay() + 6) % 7;
    const baseMonday = new Date(base);
    baseMonday.setDate(base.getDate() - baseDow);

    const target = new Date(targetIso + "T00:00:00");
    if (isNaN(target.getTime())) return;
    const targetDow = (target.getDay() + 6) % 7;
    const targetMonday = new Date(target);
    targetMonday.setDate(target.getDate() - targetDow);

    const diffWeeks = Math.round((targetMonday.getTime() - baseMonday.getTime()) / (7 * 86400000));
    setWeekOffset(diffWeeks);
    const dayNames = ["Thứ 2", "Thứ 3", "Thứ 4", "Thứ 5", "Thứ 6", "Thứ 7", "Chủ nhật"];
    setSelectedDailyDay(dayNames[targetDow] || "Thứ 2");
  }, [currentTodayIso]);
